int rowWithMax1s(vector<vector<int>> arr, int n, int m)
{
    int j = m - 1;
    int i = 0;
    int ans = -1;
    while (j >= 0 && i < n)
    {
        while (arr[i][j] == 1)
        {
            ans = i;
            j--;
        }
        if (i < n)
            i++;
    }
    return ans;
}

